const { unlinkSync, existsSync, writeFileSync } = require('node:fs');
const { join } = require('node:path');

let cleanup = 0;
const tempFiles = ['.fix-vue-imports.tmp', '.import-cache.json'];

for (const f of tempFiles) {
  const p = join(input.rootDir || '.', f);
  if (existsSync(p)) { unlinkSync(p); cleanup++; }
}

const report = {
  action: 'fix-vue-imports-batched',
  totalFiles: input.progress?.totalFiles || 0,
  fixedCount: input.fixed_count || 0,
  timestamp: new Date().toISOString()
};

writeFileSync(join(input.rootDir || '.', '.carrier', 'reports', 'fix-imports-report.json'), JSON.stringify(report, null, 2));

return { cleanup_count: cleanup, report_path: '.carrier/reports/fix-imports-report.json' };
